function lite$cpInRanges(ranges: readonly number[], cp: number): boolean {
    let lo = 0, hi = (ranges.length >>> 1);
    while (lo < hi) {
        const mid = (lo + hi) >>> 1;
        const idx = mid << 1;
        if (cp < ranges[idx]!) hi = mid;
        else if (cp > ranges[idx + 1]!) lo = mid + 1;
        else return true;
    }
    return false;
}

